package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;
@Entity @Table(name="sales_surcharge_type") public class TipoRecargo {@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="tenant_id",nullable=false,updatable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false,updatable=false)private UUID empresaId;@Column(name="name",nullable=false)private String nombre;@Column(name="normalized_name",nullable=false)private String nombreNormalizado;@Enumerated(EnumType.STRING)@Column(name="default_type",nullable=false)private TipoRecargoVenta tipoPredeterminado;@Column(name="default_value")private BigDecimal valorPredeterminado;@Enumerated(EnumType.STRING)@Column(name="tax_treatment",nullable=false)private TratamientoFiscalRecargo tratamientoFiscal=TratamientoFiscalRecargo.FOLLOW_LINE;@Column(name="editable_value",nullable=false)private boolean valorEditable=true;@Column(nullable=false)private boolean active=true;@Column(name="created_at",insertable=false,updatable=false)private OffsetDateTime creadoEn;@Column(name="created_by",updatable=false)private UUID creadoPor;@Column(name="updated_at")private OffsetDateTime actualizadoEn;@Column(name="updated_by")private UUID actualizadoPor;@Version private long version;protected TipoRecargo(){}public TipoRecargo(UUID t,UUID e,String n,String nn,TipoRecargoVenta tp,BigDecimal v,TratamientoFiscalRecargo tf,boolean ve,UUID u){tenantId=t;empresaId=e;nombre=n;nombreNormalizado=nn;tipoPredeterminado=tp;valorPredeterminado=v;tratamientoFiscal=tf;valorEditable=ve;creadoPor=u;actualizadoPor=u;actualizadoEn=OffsetDateTime.now();}public void actualizar(String n,String nn,TipoRecargoVenta tp,BigDecimal v,TratamientoFiscalRecargo tf,boolean ve,boolean a,UUID u){nombre=n;nombreNormalizado=nn;tipoPredeterminado=tp;valorPredeterminado=v;tratamientoFiscal=tf;valorEditable=ve;active=a;actualizadoPor=u;actualizadoEn=OffsetDateTime.now();}public UUID getId(){return id;}public String getNombre(){return nombre;}public TipoRecargoVenta getTipoPredeterminado(){return tipoPredeterminado;}public BigDecimal getValorPredeterminado(){return valorPredeterminado;}public TratamientoFiscalRecargo getTratamientoFiscal(){return tratamientoFiscal;}public boolean isValorEditable(){return valorEditable;}public boolean isActivo(){return active;}public long getVersion(){return version;}}
